def algorithm(func, dim, lb, ub, budget, rng):
    x = np.random.uniform(lb, ub, size=(1, dim))
    best = func(x)

    for _ in range(budget):
        # DE step
        noise = rng.uniform(0, 1, size=dim) - 0.5
        candidate = x + 0.8 * (rng.uniform(lb, ub, size=(1, dim)) - lb)
        for i in range(dim):
            if np.random.rand() < 0.2:
                candidate[0, i] = max(min(candidate[0, i], ub[i]), lb[i])

        # SA step
        new_candidate = candidate.copy()
        prob = rng.uniform(0, 1)
        for i in range(dim):
            if np.random.rand() < prob:
                new_candidate[0, i] += rng.uniform(-1e-3, 1e-3)
                new_candidate[0, i] = max(min(new_candidate[0, i], ub[i]), lb[i])

        candidate_eval = func(candidate)
        new_candidate_eval = func(new_candidate)

        if new_candidate_eval < candidate_eval:
            x = new_candidate
            best = min(best, new_candidate_eval)
        elif np.random.rand() < 0.9 and new_candidate_eval < best:
            x = new_candidate
            best = new_candidate_eval

    return x[0]

def algorithm(func, dim, lb, ub, budget, rng):
    def func_wrapper(x):
        return func(x)

    def clip_candidate(candidate):
        return np.clip(candidate, lb, ub)

    def sample_gaussian(mean, cov):
        return mean + rng.normal(size=dim) @ np.linalg.cholesky(cov)

    x = np.random.uniform(lb, ub, size=dim)
    best_x = np.copy(x)
    best_func_value = func_wrapper(best_x)

    step_size = 1
    learning_rate = 0.01

    for _ in range(budget):
        candidates = [clip_candidate(sample_gaussian(x, np.eye(dim)*step_size**2)) 
                      for _ in range(100)]

        values = [func_wrapper(candidate) for candidate in candidates]

        new_x = np.mean(candidates[np.argsort(values)[:5]], axis=0)

        if func_wrapper(new_x) < best_func_value:
            step_size *= (1 - learning_rate)
            x = np.copy(new_x)
            best_x = np.copy(x)
            best_func_value = func_wrapper(best_x)

    return best_x

